// ═══════════════════════════════════════════════════════════════════════════
//  SHOTBREAK — Agent Invocation (background, 15-minute budget)
//
//  Netlify detects the -background.js suffix and grants a 15-minute execution
//  window. The client gets a 202 immediately; this function runs to completion
//  and writes the result to Firestore for the status endpoint to serve.
//
//  POST /.netlify/functions/agent-invoke-background
//  Headers:  Authorization: Bearer <token>
//  Body:     { agent_id, input, context?, job_id }
//            job_id is generated by the client (e.g. crypto.randomUUID()).
//            The server prefixes it with the user's uid to prevent collisions.
//
//  Pairs with: agent-invoke-status.js
// ═══════════════════════════════════════════════════════════════════════════

'use strict';

const { getAgent }                                        = require('../../agents/registry');
const { verifyToken, getOrCreateUser, setCredits, getSystemToken } = require('./lib/auth');

const ANTHROPIC_URL     = 'https://api.anthropic.com/v1/messages';
const ANTHROPIC_VERSION = '2023-06-01';
const FALLBACK_MODEL    = 'claude-haiku-4-5-20251001';
const VALID_DEDUCTIONS  = new Set([5, 15, 20, 50, 75, 150, 250]);

const FIRESTORE_BASE = () =>
  `https://firestore.googleapis.com/v1/projects/${process.env.FIREBASE_PROJECT_ID}/databases/(default)/documents`;

// ── Firestore job helpers ───────────────────────────────────────────────
async function writeJob(docId, fields) {
  const token = await getSystemToken();
  const mask  = Object.keys(fields).map(k => `updateMask.fieldPaths=${encodeURIComponent(k)}`).join('&');
  const r = await fetch(`${FIRESTORE_BASE()}/agent_jobs/${docId}?${mask}`, {
    method: 'PATCH',
    headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      fields: Object.fromEntries(
        Object.entries(fields).map(([k, v]) => {
          if (v === null || v === undefined) return [k, { nullValue: null }];
          if (typeof v === 'number')  return [k, { integerValue: String(v) }];
          if (typeof v === 'boolean') return [k, { booleanValue: v }];
          if (v instanceof Date)      return [k, { timestampValue: v.toISOString() }];
          if (typeof v === 'object')  return [k, { stringValue: JSON.stringify(v) }];
          return [k, { stringValue: String(v) }];
        })
      ),
    }),
  });
  if (!r.ok) {
    const txt = await r.text().catch(() => '');
    throw new Error('JOB_WRITE_FAIL_' + r.status + ': ' + txt);
  }
}

// ── Partial JSON salvage ────────────────────────────────────────────────
function salvagePartialArray(text) {
  if (!text || typeof text !== 'string') return null;
  const m = text.match(/"([a-zA-Z_][a-zA-Z0-9_]*)"\s*:\s*\[/);
  if (!m) return null;
  const key = m[1];
  let i = m.index + m[0].length;
  const items = [];
  while (i < text.length && /\s/.test(text[i])) i++;
  while (i < text.length) {
    if (text[i] !== '{') break;
    const start = i;
    let depth = 0, inStr = false, escape = false, closed = false;
    while (i < text.length) {
      const ch = text[i];
      if (escape) { escape = false; i++; continue; }
      if (inStr) {
        if (ch === '\\') { escape = true; i++; continue; }
        if (ch === '"') inStr = false;
        i++; continue;
      }
      if (ch === '"') { inStr = true; i++; continue; }
      if (ch === '{') depth++;
      else if (ch === '}') { depth--; if (depth === 0) { i++; closed = true; break; } }
      i++;
    }
    if (!closed) break;
    try { items.push(JSON.parse(text.slice(start, i))); } catch (_) {}
    while (i < text.length && /[,\s]/.test(text[i])) i++;
  }
  return items.length ? { key, items } : null;
}

// ── Context trimmer ─────────────────────────────────────────────────────
const KEY_CAP = 15 * 1024;
function trimContext(ctx) {
  if (!ctx || typeof ctx !== 'object') return ctx;
  const out = {};
  for (const [k, v] of Object.entries(ctx)) {
    const s = JSON.stringify(v);
    out[k] = s.length <= KEY_CAP ? v : { _truncated: true, _size: s.length, _preview: s.slice(0, KEY_CAP) + '…' };
  }
  return out;
}

// ── Anthropic call with Sonnet→Haiku fallback ───────────────────────────
// No Netlify ceiling here — we have 15 minutes. Use generous timeouts.
const SONNET_TIMEOUT_MS = 90000;  // 90s — much more room in background context
const FALLBACK_TIMEOUT_MS = 60000;

async function callAnthropic(agent, input, context) {
  const userMessage = typeof input === 'string' ? input : JSON.stringify(input, null, 2);
  const trimmed     = trimContext(context);
  const brief       = trimmed ? `\n\n[CONTEXT FROM UPSTREAM AGENTS]\n${JSON.stringify(trimmed, null, 2)}` : '';

  const body = {
    model:      agent.model,
    max_tokens: agent.max_tokens || (agent.tier === 1 ? 900 : 700),
    system: [{ type: 'text', text: agent.systemPrompt, cache_control: { type: 'ephemeral' } }],
    messages: [{ role: 'user', content: `${userMessage}${brief}` }],
  };

  async function tryModel(model, timeoutMs, maxRetries = 2) {
    let attempt = 0;
    const localBody = { ...body, model };
    while (true) {
      const ctrl  = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), timeoutMs);
      try {
        const r = await fetch(ANTHROPIC_URL, {
          method: 'POST',
          headers: {
            'x-api-key':         process.env.ANTHROPIC_API_KEY,
            'anthropic-version': ANTHROPIC_VERSION,
            'anthropic-beta':    'prompt-caching-2024-07-31',
            'Content-Type':      'application/json',
          },
          body:   JSON.stringify(localBody),
          signal: ctrl.signal,
        });
        clearTimeout(timer);
        if (r.status !== 429 && r.status !== 529 && r.status !== 503) return r;
        attempt++;
        if (attempt > maxRetries) return r;
        const retryAfter = parseInt(r.headers.get('retry-after') || '0', 10);
        await new Promise(res => setTimeout(res, retryAfter > 0 && retryAfter < 10 ? retryAfter * 1000 : Math.min(4000, 1000 * attempt)));
      } catch (e) {
        clearTimeout(timer);
        if (e.name === 'AbortError') return { _stalled: true, status: 599, headers: { get: () => null } };
        throw e;
      }
    }
  }

  let res = await tryModel(agent.model, SONNET_TIMEOUT_MS, 2);
  let currentModel = agent.model;

  if (res._stalled || res.status === 429 || res.status === 529 || res.status === 503) {
    console.log(JSON.stringify({ tag: 'SB_BG_FALLBACK', agent_id: agent.id, primary_status: res.status }));
    currentModel = FALLBACK_MODEL;
    res = await tryModel(FALLBACK_MODEL, FALLBACK_TIMEOUT_MS, 3);
    if (res._stalled) throw new Error(`Both Sonnet and Haiku stalled for agent ${agent.id}`);
  }

  const raw = await res.text();
  let parsed;
  try { parsed = JSON.parse(raw); }
  catch { throw new Error(`Non-JSON from Anthropic (${res.status}): ${raw.slice(0, 400)}`); }

  if (!res.ok) throw new Error(`Anthropic error (${res.status}): ${parsed.error?.message || raw}`);

  const textBlocks = (parsed.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
  let structured = null, parseError = null;
  if (agent.outputFormat === 'json') {
    const cleaned = textBlocks.replace(/```json\s*|\s*```/g, '').trim();
    try { structured = JSON.parse(cleaned); }
    catch (e) {
      parseError = e.message;
      const salvaged = salvagePartialArray(cleaned);
      if (salvaged?.items?.length) {
        structured = { [salvaged.key]: salvaged.items, _truncated: true, _recovered_count: salvaged.items.length };
        parseError = `${parseError} (salvaged ${salvaged.items.length} ${salvaged.key})`;
      }
    }
  }

  return { raw: textBlocks, structured, parse_error: parseError, usage: parsed.usage || null, model_used: currentModel };
}

// ── Handler ─────────────────────────────────────────────────────────────
exports.handler = async (event) => {
  // Background functions always return 202 to the client immediately.
  // All real work happens after this point and is invisible to the requester.

  let payload;
  try { payload = JSON.parse(event.body || '{}'); }
  catch { return { statusCode: 400 }; }

  const { agent_id, input, context, job_id: clientJobId } = payload;
  if (!agent_id || input === undefined || !clientJobId) return { statusCode: 400 };

  let agent;
  try { agent = getAgent(agent_id); }
  catch { return { statusCode: 404 }; }

  if (!VALID_DEDUCTIONS.has(agent.credits)) return { statusCode: 500 };

  let auth;
  try { auth = await verifyToken(event); }
  catch { return { statusCode: 401 }; }

  // Safe doc id: uid prefix prevents cross-user job_id collisions.
  const docId = `${auth.uid}_${String(clientJobId).replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 64)}`;

  // Write initial job record so the status endpoint returns "pending" immediately.
  try {
    await writeJob(docId, {
      uid:       auth.uid,
      agent_id,
      status:    'running',
      createdAt: new Date(),
    });
  } catch (e) {
    console.error('SB_BG_JOB_CREATE_FAIL', e.message);
    return { statusCode: 500 };
  }

  // Credit check + deduction.
  let userCredits = 0;
  if (!auth.isOwner) {
    let user;
    try { user = await getOrCreateUser(auth.uid); }
    catch (e) {
      await writeJob(docId, { status: 'error', error: 'Credit lookup failed: ' + e.message, completedAt: new Date() }).catch(() => {});
      return { statusCode: 500 };
    }
    userCredits = user?.credits || 0;
    if (userCredits < agent.credits) {
      await writeJob(docId, { status: 'error', error: 'Insufficient credits', completedAt: new Date() }).catch(() => {});
      return { statusCode: 402 };
    }
    try { await setCredits(auth.uid, userCredits - agent.credits); }
    catch (e) {
      await writeJob(docId, { status: 'error', error: 'Credit deduction failed: ' + e.message, completedAt: new Date() }).catch(() => {});
      return { statusCode: 500 };
    }
  }

  // Run the agent.
  let result;
  try {
    result = await callAnthropic(agent, input, context);
  } catch (e) {
    if (!auth.isOwner) {
      try { await setCredits(auth.uid, userCredits); } catch (_) {}
    }
    await writeJob(docId, { status: 'error', error: e.message, completedAt: new Date() }).catch(() => {});
    return { statusCode: 502 };
  }

  // Write success.
  await writeJob(docId, {
    status:            'complete',
    output:            result.structured || result.raw,
    raw:               result.raw,
    parse_error:       result.parse_error || null,
    credits_charged:   auth.isOwner ? 0 : agent.credits,
    credits_remaining: auth.isOwner ? 999999 : userCredits - agent.credits,
    is_owner:          auth.isOwner,
    model_used:        result.model_used,
    completedAt:       new Date(),
  }).catch(e => console.error('SB_BG_JOB_COMPLETE_FAIL', e.message));

  console.log(JSON.stringify({
    tag: 'SB_BG_COMPLETE', agent_id, uid: auth.uid,
    credits: auth.isOwner ? 0 : agent.credits, model: result.model_used,
  }));

  return { statusCode: 200 };
};
